import{az as a,P as n,Q as l,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const F=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/调试工具/Charles.md","filePath":"server/调试工具/Charles.md","lastUpdated":1785339991000}'),e={name:"server/调试工具/Charles.md"};function o(p,s,c,i,r,y){return n(),l("div",null,[...s[0]||(s[0]=[t(`<h2 id="charles-抓包工具" tabindex="-1">Charles 抓包工具 <a class="header-anchor" href="#charles-抓包工具" aria-label="Permalink to “Charles 抓包工具”">​</a></h2><p><a href="https://www.charlesproxy.com/" target="_blank" rel="noreferrer">Charles 官方网站</a></p><p>Charles 是一款 HTTP/HTTPS 代理服务器工具，能够截取并分析本机与互联网之间的网络请求。它广泛用于接口调试、Mock 数据、弱网模拟等场景，是前端和移动端开发者的常用调试利器。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>请求抓包</td><td>拦截并展示所有 HTTP/HTTPS 请求与响应</td></tr><tr><td>HTTPS 解密</td><td>通过安装根证书解密 HTTPS 流量</td></tr><tr><td>请求/响应修改</td><td>Map Local、Rewrite 动态修改数据</td></tr><tr><td>弱网模拟</td><td>模拟 3G/4G/断网等网络环境</td></tr><tr><td>重复请求</td><td>Repeat / Repeat Advanced 反复发送请求</td></tr><tr><td>断点调试</td><td>对特定请求设置断点，手动修改后放行</td></tr></tbody></table><h2 id="基本配置" tabindex="-1">基本配置 <a class="header-anchor" href="#基本配置" aria-label="Permalink to “基本配置”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 1. 启动 Charles，默认代理端口为 8888</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    Proxy -&gt; Proxy Settings -&gt; HTTP Proxy -&gt; Port: 8888</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 勾选 macOS Proxy 自动代理系统流量</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    Proxy -&gt; macOS Proxy</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. HTTPS 抓包需要安装根证书并信任</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    Help -&gt; SSL Proxying -&gt; Install Charles Root Certificate</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    在钥匙串中设置为&quot;始终信任&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 启用 HTTPS 解密</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    Proxy -&gt; SSL Proxying Settings -&gt; 勾选 Enable SSL Proxying</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    添加需要解密的 Host:Port（如 *:443）</span></span></code></pre></div><h2 id="抓包分析" tabindex="-1">抓包分析 <a class="header-anchor" href="#抓包分析" aria-label="Permalink to “抓包分析”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># Charles 主界面按请求域名分组展示</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 点击请求可查看详情：</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Overview：请求概览（URL、方法、状态码、耗时）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Request：请求头与请求体</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Response：响应头与响应体</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Summary：请求/响应大小、时间线</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Chart：时间消耗分布图</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 常用筛选操作：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 在底部 Filter 框输入关键词过滤</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 右键域名 -&gt; Focus 聚焦关注的目标</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - View -&gt; Focused Only 仅显示关注的请求</span></span></code></pre></div><h2 id="map-local-本地映射" tabindex="-1">Map Local 本地映射 <a class="header-anchor" href="#map-local-本地映射" aria-label="Permalink to “Map Local 本地映射”">​</a></h2><p>将接口响应替换为本地文件，用于 Mock 数据调试。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 配置步骤：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. Tools -&gt; Map Local -&gt; 勾选 Enable Map Local</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. Add 添加映射规则：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Protocol: https</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Host: api.example.com</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Path: /api/users</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Local path: /Users/dev/mock/users.json</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 请求该接口时，Charles 返回本地 JSON 文件内容</span></span></code></pre></div><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">code</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 200</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">data</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> [</span></span>
<span class="line"><span style="color:#89DDFF;">    {</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">id</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 1</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">name</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">Mock Alice</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">age</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 25</span><span style="color:#89DDFF;"> },</span></span>
<span class="line"><span style="color:#89DDFF;">    {</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">id</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 2</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">name</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">Mock Bob</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#FFCB6B;">age</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#F78C6C;"> 30</span><span style="color:#89DDFF;"> }</span></span>
<span class="line"><span style="color:#89DDFF;">  ]</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><h2 id="rewrite-规则修改" tabindex="-1">Rewrite 规则修改 <a class="header-anchor" href="#rewrite-规则修改" aria-label="Permalink to “Rewrite 规则修改”">​</a></h2><p>动态修改请求或响应内容，无需准备本地文件。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 配置步骤：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. Tools -&gt; Rewrite -&gt; 勾选 Enable Rewrite</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. Add 添加规则集，配置 Location（目标接口）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 添加 Rewrite 规则：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Type: Body</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Match: &quot;production&quot;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Replace: &quot;staging&quot;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    -&gt; 将响应中的 production 替换为 staging</span></span></code></pre></div><h2 id="弱网模拟" tabindex="-1">弱网模拟 <a class="header-anchor" href="#弱网模拟" aria-label="Permalink to “弱网模拟”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 配置步骤：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. Proxy -&gt; Throttle Settings -&gt; 勾选 Enable Throttling</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 选择预设带宽或自定义：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Bandwidth: 256 KB/s（下行带宽）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Utilisation: 100%</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - Round-trip latency: 300 ms（延迟）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - MTU: 1500</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 可针对特定域名单独设置弱网</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 常见弱网预设：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 3G: ~400 Kbps, 延迟 400ms</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 2G: ~30 Kbps, 延迟 500ms</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 断网: Bandwidth 设为 0</span></span></code></pre></div><h2 id="移动端抓包" tabindex="-1">移动端抓包 <a class="header-anchor" href="#移动端抓包" aria-label="Permalink to “移动端抓包”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># iOS 抓包配置</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. 手机与电脑同一 Wi-Fi</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 手机 Wi-Fi 设置 -&gt; HTTP 代理 -&gt; 手动</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - 服务器：电脑 IP（如 192.168.1.100）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">#    - 端口：8888</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. 手机 Safari 访问 chls.pro/ssl 安装证书</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 设置 -&gt; 通用 -&gt; 关于本机 -&gt; 证书信任设置 -&gt; 启用信任</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Android 抓包配置</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. 同一 Wi-Fi，设置代理（同上）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. 下载并安装 Charles 证书</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. Android 7+ 需将证书安装到系统级（需 root）或使用 debug 包</span></span></code></pre></div><h2 id="charles-vs-其他抓包工具" tabindex="-1">Charles vs 其他抓包工具 <a class="header-anchor" href="#charles-vs-其他抓包工具" aria-label="Permalink to “Charles vs 其他抓包工具”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>平台</th><th>特色</th><th>适用场景</th></tr></thead><tbody><tr><td>Charles</td><td>macOS/Win/Linux</td><td>GUI 友好，功能全面</td><td>前端/移动端日常调试</td></tr><tr><td>Fiddler</td><td>Win 为主</td><td>免费，插件丰富</td><td>Windows 环境抓包</td></tr><tr><td>Wireshark</td><td>全平台</td><td>底层协议分析</td><td>网络层问题排查</td></tr><tr><td>mitmproxy</td><td>命令行</td><td>可编程，支持 Python 脚本</td><td>自动化抓包</td></tr></tbody></table><p>Charles 是前端开发者必备的网络调试工具。通过 Map Local 和 Rewrite 功能，可以在不修改后端代码的情况下灵活调试前端逻辑；弱网模拟帮助发现网络异常下的用户体验问题；移动端抓包则是移动开发调试的关键手段。</p>`,23)])])}const D=a(e,[["render",o]]);export{F as __pageData,D as default};
